/**
 * The module's top orchestration layer: wires request parsing, the same-origin guard, a route's
 * `handle`, and response serialization into a single Express route handler. This is the only
 * file in the module that knows about Express `req`/`res` on the mounting side.
 */
import { inspect } from 'node:util';
import { redactSecrets } from '@jini-ai/core';
import { randomUUID } from 'node:crypto';
import type { Express, Request, Response } from 'express';
import { createApiError, type ApiError } from '@jini-ai/protocol';
import { rawInput } from './request.js';
import { sendApiError, sendJson, statusForError } from './response.js';
import { guardSameOrigin, type OriginContext } from './origin.js';
import type { JsonRouteAuthorize, JsonRouteSpec, Result } from './types.js';

export interface AdapterInternalErrorContext {
  /** HTTP method of the route whose handler threw. */
  readonly method: string;
  /** Registered path of the route whose handler threw. */
  readonly path: string;
  /** Echoed back to the caller as the response's `requestId`, so an operator can tie a user's report to this log line. */
  readonly correlationId: string;
  /** The exception exactly as thrown — never sent to the caller. */
  readonly error: unknown;
}

/** Server startup state a mounted route needs to evaluate its same-origin guard. */
export interface AdapterContext extends OriginContext {
  /**
   * Host-owned sink for the real exception behind a generic `INTERNAL_ERROR` response (SEC-005).
   * Defaults to `console.error`. Mirrors the per-module `onInternalError` seams (`connectors.ts`,
   * `delegated-tools.ts`, …); this one is the catch-all for a route that throws outside its own
   * guarded path.
   */
  readonly onInternalError?: (context: AdapterInternalErrorContext) => void;
}

function defaultInternalErrorSink(context: AdapterInternalErrorContext): void {
  // Exceptions can echo credentials; inspect preserves stacks and codes before shared redaction.
  // eslint-disable-next-line no-console
  console.error(`[@jini-ai/http-kit] internal error (${context.method.toUpperCase()} ${context.path}, correlationId=${context.correlationId})`, redactSecrets({ input: inspect(context.error) }, { redactPii: false }));
}

/**
 * Thrown by a route's `handle` — or by anything it calls, at any depth — to bypass the SEC-005
 * redaction below with an `ApiError` the throwing code has already decided is safe for the caller
 * to see. This is the general-purpose version of a carve-out every consuming module of this catch
 * otherwise hand-rolls for itself: `attachments.ts`'s `AttachmentRejectedError`/
 * `respondToUploadFailure`, and `delegated-tools.ts`'s `errorKind: 'validation'` split on
 * `ToolExecutionResult`, both exist because nothing at THIS layer distinguished "the code that threw
 * already classified this as caller-safe" from "something unanticipated happened" — so a route with
 * no such local carve-out has no way to disclose even a deliberately-safe failure, and everything it
 * throws redacts identically to a stray filesystem or driver error.
 *
 * Prefer returning `err(apiError)` from `handle` when the failure is anticipated at that point —
 * that path already reaches the caller with full fidelity and never touches this catch at all. This
 * class exists for the same kind of failure discovered a level deeper: inside an awaited call
 * `handle` itself did not (or could not) wrap in its own `try`.
 *
 * Not a way to defeat SEC-005: the only way to reach the branch that reads this class is for code to
 * construct one itself, naming the exact `ApiError` — code and message — it is choosing to disclose.
 * Any thrown value that is not this class (including a plain `Error` with an actionable-looking
 * message) still redacts exactly as before; nothing here widens what a route can leak by accident.
 */
export class ClientFacingError extends Error {
  readonly apiError: ApiError;

  constructor({ apiError }: { readonly apiError: ApiError }, _optional: Record<string, never> = {}) {
    super(apiError.message);
    this.name = 'ClientFacingError';
    this.apiError = apiError;
  }
}

/**
 * Combines required route fields and optional settings into a fresh spec while pinning its generic
 * parameters at the definition site so callers do not have to repeat them. Optional settings take
 * precedence. The returned spec is consumed by `mountJsonRoute` (live)
 * and by tests (direct invocation of `route.parse` / `route.handle`).
 * @param optionalArgs - Origin/success policy and optional injected host ports.
 * @returns A fresh route spec; never mutates either argument.
 * @complexity O(1) time/space for the fixed spec fields.
 */
export function defineJsonRoute<Input, Output, Deps, Context = undefined>(requiredArgs: Omit<JsonRouteSpec<Input, Output, Deps, Context>, 'requireSameOrigin' | 'successStatus' | 'ports'>, optionalArgs: Pick<JsonRouteSpec<Input, Output, Deps, Context>, 'requireSameOrigin' | 'successStatus' | 'ports'> = {}
): JsonRouteSpec<Input, Output, Deps, Context> {
  return { ...requiredArgs, ...optionalArgs };
}

/**
 * Mounts one JsonRouteSpec on an Express app. The Adapter is the only code here that knows
 * about req/res; the route's parse and handle functions operate on `RouteInputContext` and
 * `Deps` respectively, so they are unit testable without Express. Optional host ports preserve
 * workspace/auth/error policy without coupling this toolkit to a domain. An origin context is
 * required only for routes that opt into the same-origin guard.
 * @returns Void; registers one handler, without starting a listener.
 * @complexity O(1) setup and per-request overhead, plus parsing, host ports and handling.
 */
export function mountJsonRoute<Input, Output, Deps, Context = undefined>({ app, spec, deps, adapter }: { readonly app: Express; readonly spec: JsonRouteSpec<Input, Output, Deps, Context>; readonly deps: Deps; readonly adapter?: AdapterContext }, _optional: Record<string, never> = {}
): void {
  app[spec.method](spec.path, async (req: Request, res: Response) => {
    // The client-disconnect signal a `handle` can opt into via optional arguments. Observed on `res`,
    // not `req` — `sse.ts` already established why for this exact "detect a disconnect before
    // ever writing a response" shape (its own doc: safe to register "before `open` is ever
    // called"). `req`'s own `'close'` was tried first here and reverted: on a REAL socket, a
    // POST's body is fully read by Express's body parser before this handler ever runs, and that
    // finishes the *request* stream — firing `req`'s `'close'` immediately, long before any
    // response is sent, with no disconnect having happened at all. `res`'s `'close'` isn't
    // entangled with the request body's lifecycle, only with the response's own connection, so it
    // doesn't share that false positive. Registered before anything awaits and unconditionally
    // detached in `finally` below, so it never outlives one request.
    const abortController = new AbortController();
    const onResponseClose = () => abortController.abort();
    // Optional-called rather than assumed present: a real Express `Response` always has `.on`, but
    // several existing unit tests drive `mountJsonRoute` against a minimal `{status,json}` double
    // that doesn't implement `EventEmitter` at all. Those callers simply never observe an abort,
    // which is the correct behavior for a double that never fires `close` anyway.
    res.on?.('close', onResponseClose);
    try {
      const raw = rawInput({ req });
      if (spec.ports?.workspace) await spec.ports.workspace({ raw, deps });
      if (!allowRouteOrigin({ req, res, spec, adapter })) return;
      let context: Context | undefined;
      if (spec.ports?.authenticate) context = await spec.ports.authenticate({ raw, res, deps });
      const parsed = spec.parse(raw);
      if (!parsed.ok) {
        sendApiError({ res, status: statusForError({ error: parsed.error }), error: parsed.error });
        return;
      }
      // The route chooses where authorization occurs: reads may authorize before validation,
      // while writes must reject an inconsistent tenant target before asking for a permission.
      const authorize: JsonRouteAuthorize = async ({ permission, entityType }) => {
        if (!spec.ports?.authorize) throw new Error('JSON route authorizer is required');
        await spec.ports.authorize({ context, deps, permission, entityType });
      };
      const result = await spec.handle({ input: parsed.value, deps, context, authorize }, { signal: abortController.signal });
      sendRouteResult({ res, result, spec, signal: abortController.signal });
    } catch (e) {
      sendRouteException({ res, spec, adapter, error: e });
    } finally {
      res.off?.('close', onResponseClose);
    }
  });
}

function allowRouteOrigin({ req, res, spec, adapter }: {
  readonly req: Request;
  readonly res: Response;
  readonly spec: Pick<JsonRouteSpec<unknown, unknown, unknown>, 'requireSameOrigin'>;
  readonly adapter: AdapterContext | undefined;
}, _optional: Record<string, never> = {}): boolean {
  if (!spec.requireSameOrigin) return true;
  if (!adapter) throw new Error('same-origin adapter context is required');
  const origin = guardSameOrigin({ req, origin: adapter });
  if (origin.ok) return true;
  sendApiError({ res, status: statusForError({ error: origin.error }), error: origin.error });
  return false;
}

function sendRouteResult<Output>({ res, result, spec, signal }: {
  readonly res: Response;
  readonly result: Result<Output>;
  readonly spec: Pick<JsonRouteSpec<unknown, Output, unknown>, 'successStatus'>;
  readonly signal: AbortSignal;
}, _optional: Record<string, never> = {}): void {
  // `signal` can only have been aborted by `onResponseClose` firing while the
  // `await spec.handle` in the request handler was pending — nothing here runs concurrently
  // with it — so this unambiguously means the client was already gone before any response was
  // sent. Writing one now would be wasted work at best and, worse, would route a benign
  // disconnect into the SEC-005 catch as a false internal error if the socket rejects the write.
  if (signal.aborted) return;
  if (!result.ok) {
    sendApiError({ res, status: statusForError({ error: result.error }), error: result.error });
    return;
  }
  sendJson({ res, status: spec.successStatus ?? 200, body: result.value });
}

function sendRouteException<Deps, Context>({ res, spec, adapter, error: e }: {
  readonly res: Response;
  readonly spec: Pick<JsonRouteSpec<unknown, unknown, Deps, Context>, 'method' | 'path' | 'ports'>;
  readonly adapter: AdapterContext | undefined;
  readonly error: unknown;
}, _optional: Record<string, never> = {}): void {
  // An explicit host error port owns exception classification and serialization, including
  // its guard rejections. Hosts without it retain the SEC-005 policy below unchanged.
  if (spec.ports?.onError) {
    spec.ports.onError({ res, error: e });
    return;
  }
  // A route (or something it called) already classified this failure as safe to disclose —
  // see `ClientFacingError`'s own doc. Sent verbatim, at its own status; never routed to the
  // SEC-005 sink below, because nothing unanticipated happened.
  if (e instanceof ClientFacingError) {
    sendApiError({ res, status: statusForError({ error: e.apiError }), error: e.apiError });
    return;
  }
  // SEC-005. This catch exists for exceptions no route anticipated, which makes it precisely
  // the path most likely to be holding something private: a driver error naming a database
  // file, a connection string, a credential a provider echoed back. Serializing `e.message`
  // into the response handed all of that to the caller — and because `health.ts`'s probes are
  // mounted ahead of the security middleware and exempted from the bearer gate, an unauthorized
  // caller could read it too, simply by getting a readiness dependency to fail. The real error
  // still reaches the operator through the sink, correlated to what the caller was told.
  const correlationId = randomUUID();
  const sink = adapter?.onInternalError ?? defaultInternalErrorSink;
  sink({ method: spec.method, path: spec.path, correlationId, error: e });
  sendApiError({ res, status: 500, error: createApiError({ code: 'INTERNAL_ERROR', message: 'The server could not finish this request. Check whether your change was saved, then copy the request ID and report this problem.' },
    { requestId: correlationId }) });
}

/**
 * @file Shared site-path checks: decoded, dot-resolved segments and origin tracking.
 *
 * Why the rule is not `path.startsWith("/admin")`:
 * - `/administer-survey` is ordinary site content and must keep working, so the comparison is per
 *   SEGMENT, not per prefix.
 * - `/%61dmin` is compared AFTER one percent-decode, not on the raw bytes. Express (which routes on
 *   the raw path) and browsers (which do not decode `%61` in a path) do NOT treat it as `/admin`; a
 *   proxy or server that decodes before routing does. Refusing it is deliberate over-refusal — the
 *   safe direction for a rule whose job is to keep public redirects and fetches off the admin
 *   surface.
 * - `/ADMIN` reaches the same Express mount (Express matches paths case-insensitively by default),
 *   so the comparison is case-folded.
 * - `/blog/../admin` is `/admin` by the time a browser issues the request, so dot segments are
 *   resolved first.
 *
 */

/** {@link checkSitePathname}'s verdict. Every arm is a refusal except `ok`. */
export type SitePathCheck =
  | { kind: "ok" }
  /** `decodeURIComponent` threw — a stray or truncated `%` sequence. */
  | { kind: "malformed-encoding" }
  /** Decodes to a backslash (a `/` to URL parsers) or a C0/C1 control character (CR/LF splitting). */
  | { kind: "disallowed-character" }
  | { kind: "reserved"; surface: string };

/** {@link checkSiteRelativeTarget}'s verdict — {@link SitePathCheck} plus the two structural arms
 *  that only apply when the input is still a raw, unparsed reference. */
export type SiteRelativeTargetCheck =
  | SitePathCheck
  /** `new URL()` could not parse it at all. */
  | { kind: "unparseable" }
  /** Parses, but resolves to a DIFFERENT host — e.g. `/\evil.example`, which starts with a single
   *  slash yet is `//evil.example` to a URL parser, so a `startsWith("//")` test never sees it. */
  | { kind: "off-origin" };

/**
 * Two hosts this deployment can never actually reach, used only so `new URL()` has a base to
 * resolve a site-relative reference against. `.invalid` is reserved by RFC 2606 precisely for this.
 *
 * There are TWO because one base is NAMEABLE (t85 independent review, 2026-09-16). With a single
 * base, `//reserved-path-probe.invalid/x` resolves to that very origin, so "did the origin survive"
 * answered yes for a reference that leaves the site — reachable as `/store/buy`'s `returnTo`, which
 * sent `Location: //reserved-path-probe.invalid/x`. Requiring the resolved origin to TRACK whichever
 * base it was given leaves no origin an input can name, which is a structural answer rather than a
 * denylist of the sentinel's spellings (the same reasoning as the probe itself — see
 * {@link checkSiteRelativeTarget}). Both are bare origins, so a reference resolves to the same
 * pathname against either.
 */
// eslint-disable-next-line sonarjs/no-clear-text-protocols -- Reserved .invalid probe origin used only for URL parsing; no network transport is invoked.
const PROBE_ORIGIN = "http://reserved-path-probe.invalid";
// eslint-disable-next-line sonarjs/no-clear-text-protocols -- Reserved .invalid probe origin used only for URL parsing; no network transport is invoked.
const SECOND_PROBE_ORIGIN = "http://reserved-path-probe-2.invalid";

/**
 * Whether `value` contains a C0 or C1 control character.
 *
 * CR/LF in a request target is HTTP request splitting and in a `Location` header is response
 * splitting; NUL and friends are path-truncation tricks.
 *
 * @param required.value - Any string, already decoded or not.
 * @returns `true` if any code unit is in `U+0000`–`U+001F` or `U+007F`–`U+009F`.
 * @complexity O(n) in the string length.
 * @example hasControlCharacter({ value: "/ok" }, {}); // => false
 */
export function hasControlCharacter(
  { value }: { value: string },
  _optional: Record<string, never> = {},
): boolean {
  for (let index = 0; index < value.length; index += 1) {
    const code = value.charCodeAt(index);
    if (code <= 0x1f || (code >= 0x7f && code <= 0x9f)) return true;
  }
  return false;
}

/**
 * Resolve `.` and `..` segments, RFC 3986 §5.2.4 style, on an already-decoded path.
 *
 * Done by hand rather than with a second `new URL()` pass because a decoded path can contain a
 * literal `?` or `#` (from `%3F`/`%23`), and the URL parser would treat those as a query/fragment
 * delimiter and TRUNCATE the path — turning `/x#/../admin` into `/x` and losing the very segment
 * this check exists to find. A browser does no such thing: it never decodes `%23` before splitting
 * the path, so the truncation would be a false negative, not a match for real behavior.
 *
 * Empty segments are dropped, so `//admin` collapses to `/admin`. That is deliberately stricter
 * than a URL parser (which preserves `//`); over-matching here only ever refuses more.
 *
 * @param path - A decoded path, expected to start with `/`.
 * @returns The path with dot segments removed, always starting with `/`.
 * @complexity O(n) in the path length.
 * @example resolveDotSegments("/blog/../admin"); // => "/admin"
 */
function resolveDotSegments(path: string): string {
  const out: string[] = [];
  for (const segment of path.split("/")) {
    if (segment === "" || segment === ".") continue;
    if (segment === "..") out.pop();
    else out.push(segment);
  }
  return `/${out.join("/")}`;
}

/**
 * The actual per-segment rule, on a pathname string that is guaranteed to have come from a real
 * `URL` (see {@link checkSitePathname}, this function's only caller). Kept private: a bare
 * string carries no proof it was ever parsed — the query/fragment stripping, dot-segment removal
 * relative to a real origin, etc. are exactly what `new URL()` already did before that caller
 * reaches this. Do not export this directly.
 *
 * Check the undecoded first segment too: Express mounts `/admin/..%2fpublic` under `/admin`,
 * even though decoding and resolving dot segments produces `/public`.
 * Order is load-bearing for the decoded check: decode ONCE, then resolve dot segments, then compare
 * the first segment case-folded. Decoding first is what catches `/%61dmin` (over-refusal for Express
 * and browsers, a real match for a decoding proxy — see the module doc); resolving dot segments after the decode is
 * what catches `/blog/%2e%2e/admin`. Exactly one decode pass models one decoding intermediary:
 * `/%2561dmin` would need two, so it stays allowed.
 *
 * @param required.pathname - An already-parsed `URL`'s `.pathname` (no query, no fragment).
 * @param required.reservedSegments - First segments reserved by the host, stored case-folded.
 * @returns `{ kind: "ok" }` when it is ordinary site content; otherwise the arm naming the refusal.
 * @complexity O(n) in the pathname length.
 */
function checkDecodedSitePathname(
  { pathname, reservedSegments }: { pathname: string; reservedSegments: ReadonlySet<string> },
  _optional: Record<string, never> = {},
): SitePathCheck {
  let decoded: string;
  try {
    decoded = decodeURIComponent(pathname);
  } catch {
    return { kind: "malformed-encoding" };
  }
  if (decoded.includes("\\") || hasControlCharacter({ value: decoded }, {})) return { kind: "disallowed-character" };

  const rawFirst = pathname.slice(1).split("/", 1).join("").toLowerCase();
  if (reservedSegments.has(rawFirst)) return { kind: "reserved", surface: rawFirst };

  // `resolveDotSegments` always returns a path with a leading "/", so the first segment is
  // everything after it up to the next "/" — `split(..., 1)` yields exactly that one element.
  const first = resolveDotSegments(decoded).slice(1).split("/", 1).join("").toLowerCase();
  if (reservedSegments.has(first)) return { kind: "reserved", surface: first };
  return { kind: "ok" };
}

/**
 * Classify an already-parsed URL's pathname against the admin application's URL space.
 *
 * Takes the {@link URL} itself, not a bare pathname string, so this cannot be handed a raw,
 * unparsed reference by accident: a string has no way to prove it went through `new URL()` first,
 * and this rule's whole design (see the module doc) depends on comparing the DECODED, dot-resolved
 * form a URL parser would actually produce. A caller that only has a raw string — a stored redirect
 * target, anything from user input — must go through {@link checkSiteRelativeTarget} instead, which
 * parses it (and rejects what doesn't parse) before this check ever runs.
 *
 * PRECONDITION: the caller has already established that `url` is on the site's own origin. This
 * function reads only `pathname`, so `new URL("//admin", base)` (host `admin`, pathname `/`)
 * returns `ok`. It deliberately does not compare origins itself: `platform/routing` cannot use
 * `features/origin`'s normalizer, and a string `URL.origin` comparison is wrong for redirect
 * candidates (`https://site./admin`). Callers: `checkSiteRelativeTarget` (probe-origin check),
 * `site-inspection`'s `resolveWithinOrigin`, and `features/redirects/reserved-destination.ts` (the
 * origin oracle's `isSameOrigin`).
 *
 * @param required.url - An already-parsed `URL`; only `url.pathname` is read.
 * @param required.reservedSegments - First segments reserved by the host, stored case-folded.
 * @returns `{ kind: "ok" }` when it is ordinary site content; otherwise the arm naming the refusal.
 * @complexity O(n) in the pathname length.
 * @example checkSitePathname({ url: new URL("/administer-survey", "http://x.invalid"), reservedSegments: new Set(["admin", "api"]) }, {}); // => { kind: "ok" }
 * @example checkSitePathname({ url: new URL("/%61dmin/settings", "http://x.invalid"), reservedSegments: new Set(["admin", "api"]) }, {}); // => { kind: "reserved", surface: "admin" }
 */
export function checkSitePathname(
  { url, reservedSegments }: { url: URL; reservedSegments: ReadonlySet<string> },
  _optional: Record<string, never> = {},
): SitePathCheck {
  return checkDecodedSitePathname({ pathname: url.pathname, reservedSegments }, {});
}

/**
 * Classify a raw, site-relative reference (a stored redirect target, a caller-supplied path)
 * against the admin application's URL space, including the structural check that it is site-
 * relative at all.
 *
 * The structural pass runs FIRST and matters on its own: `/\evil.example` begins with exactly one
 * slash, so a `startsWith("//")` or scheme test calls it site-relative, while `new URL()` — and
 * every browser following a `Location` — reads the backslash as a separator and lands on
 * `evil.example`. Resolving against a probe origin and asserting the origin TRACKED that base is a
 * structural answer to that instead of a pattern someone has to keep correct — done against two
 * different bases so the probe origin itself is not a nameable way to pass (see
 * {@link PROBE_ORIGIN}).
 *
 * @param required.raw - The untrusted reference, expected to be site-relative.
 * @param required.reservedSegments - First segments reserved by the host, stored case-folded.
 * @returns `{ kind: "ok" }` when it stays on this site and names ordinary content; otherwise the
 * arm naming the refusal.
 * @complexity O(n) in the reference length.
 * @example checkSiteRelativeTarget({ raw: "/new", reservedSegments: new Set(["admin", "api"]) }, {}); // => { kind: "ok" }
 * @example checkSiteRelativeTarget({ raw: "/\\evil.example", reservedSegments: new Set(["admin", "api"]) }, {}); // => { kind: "off-origin" }
 */
export function checkSiteRelativeTarget(
  { raw, reservedSegments }: { raw: string; reservedSegments: ReadonlySet<string> },
  _optional: Record<string, never> = {},
): SiteRelativeTargetCheck {
  if (hasControlCharacter({ value: raw }, {})) return { kind: "disallowed-character" };
  let parsed: URL;
  let reparsed: URL;
  try {
    parsed = new URL(raw, PROBE_ORIGIN);
    reparsed = new URL(raw, SECOND_PROBE_ORIGIN);
  } catch {
    return { kind: "unparseable" };
  }
  if (parsed.origin !== PROBE_ORIGIN || reparsed.origin !== SECOND_PROBE_ORIGIN) return { kind: "off-origin" };
  return checkSitePathname({ url: parsed, reservedSegments }, {});
}
